// destinations (positions match the silhouette)
type Destination = { name: string; desc: string; tours: number; from: string; img?: string; packageSlug?: string };
type StatePin = {
  name: string; x: number; y: number; img: string; count: number; price: string;
  note: string; blurb: string; destinations: Destination[];
};

// Helper: derive per-state metadata from the package catalogue.
function statePackages(stateName: string) {
  return packages.filter((p) => p.states.includes(stateName));
}
function stateStartingFrom(stateName: string): string {
  const pkgs = statePackages(stateName);
  if (!pkgs.length) return "On request";
  const min = Math.min(...pkgs.map((p) => startingFrom(p.pricing)));
  return formatINR(min);
}
function destinationsFor(stateName: string, names: string[]): Destination[] {
  return names.map((n) => {
    const meta = DESTINATION_META[n.toLowerCase()];
    const matches = packages.filter(
      (p) => p.states.includes(stateName) && p.destinations.some((d) => d.toLowerCase().includes(n.toLowerCase())),
    );
    const matchedPkg = meta?.packageSlug
      ? packages.find((p) => p.slug === meta.packageSlug)
      : matches[0];
    const from = matchedPkg
      ? formatINR(startingFrom(matchedPkg.pricing))
      : (matches.length ? formatINR(Math.min(...matches.map((m) => startingFrom(m.pricing)))) : stateStartingFrom(stateName));
    return {
      name: n,
      desc: meta?.desc ?? `Curated visits in and around ${n}.`,
      tours: (matchedPkg ? 1 : matches.length) || 1,
      from,
      img: meta?.img,
      packageSlug: meta?.packageSlug ?? matchedPkg?.slug,
    };
  });
}

