export function IndiaMap() {
  const [active, setActive] = useState(0);
  const [destIndex, setDestIndex] = useState<number | null>(null);
  const [kanpurOpen, setKanpurOpen] = useState(false);
  const a = pins[active];
  const selectedDest = destIndex !== null ? a.destinations[destIndex] : null;
  const displayName = selectedDest?.name ?? a.name;
  const displayDesc = selectedDest?.desc ?? a.blurb;
  const displayPrice = selectedDest?.from ?? a.price;
  const displayTours = selectedDest?.tours ?? a.count;

  // reset destination selection when state changes
  useEffect(() => { setDestIndex(null); }, [active]);

  useEffect(() => {
    if (!kanpurOpen) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setKanpurOpen(false);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [kanpurOpen]);


  return (
    <section id="map" className="relative py-5 md:py-6 lg:py-8 px-6 overflow-hidden">
      <div className="mx-auto max-w-7xl">
        <SectionHeader
          eyebrow="Across India"
          title="From Kanpur to every corner of India."
          subtitle="Our head office in Kanpur dispatches curated journeys across the subcontinent — from Himalayan passes to coastal sunsets."
        />

        <div className="mt-8 md:mt-9 grid grid-cols-1 lg:grid-cols-[1.2fr_1fr] gap-8 lg:gap-10 items-stretch">
          {/* Map */}
          <div className="relative h-full glass-strong rounded-3xl p-6 overflow-hidden">
            {/* Ambient light */}
            <div
              className="absolute inset-0 opacity-50"
              style={{
                background:
                  "radial-gradient(circle at 50% 32%, oklch(0.82 0.14 85 / 0.35), transparent 55%), radial-gradient(circle at 80% 90%, oklch(0.45 0.12 270 / 0.25), transparent 60%)",
              }}
            />
            {/* Subtle grid */}
            <div
              className="absolute inset-0 opacity-[0.07] mix-blend-screen pointer-events-none"
              style={{
                backgroundImage:
                  "linear-gradient(oklch(0.78 0.13 85) 1px, transparent 1px), linear-gradient(90deg, oklch(0.78 0.13 85) 1px, transparent 1px)",
                backgroundSize: "32px 32px",
              }}
            />

            <svg
              viewBox="0 0 100 120"
              className="relative w-full h-full drop-shadow-[0_25px_45px_rgba(0,0,0,0.55)]"
              preserveAspectRatio="xMidYMid meet"
              style={{ transform: "perspective(900px) rotateX(8deg)" }}
            >
              <defs>
                <linearGradient id="indiaFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="oklch(0.82 0.14 85)" stopOpacity="0.22" />
                  <stop offset="55%" stopColor="oklch(0.45 0.08 260)" stopOpacity="0.28" />
                  <stop offset="100%" stopColor="oklch(0.18 0.03 260)" stopOpacity="0.35" />
                </linearGradient>
                <linearGradient id="indiaStroke" x1="0" y1="0" x2="1" y2="1">
                  <stop offset="0%" stopColor="oklch(0.92 0.14 88)" stopOpacity="0.9" />
                  <stop offset="100%" stopColor="oklch(0.55 0.10 80)" stopOpacity="0.5" />
                </linearGradient>
                <radialGradient id="goldOrb" cx="50%" cy="50%" r="50%">
                  <stop offset="0%" stopColor="oklch(0.98 0.12 88)" stopOpacity="1" />
                  <stop offset="60%" stopColor="oklch(0.82 0.14 85)" stopOpacity="0.6" />
                  <stop offset="100%" stopColor="oklch(0.82 0.14 85)" stopOpacity="0" />
                </radialGradient>
                <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                  <feGaussianBlur stdDeviation="0.7" result="b" />
                  <feMerge>
                    <feMergeNode in="b" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
                <filter id="strongGlow" x="-50%" y="-50%" width="200%" height="200%">
                  <feGaussianBlur stdDeviation="1.8" result="b" />
                  <feMerge>
                    <feMergeNode in="b" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>

                {/* Route paths (curved) for particles to follow */}
                {pins.map((p, i) => {
                  const mx = (KANPUR.x + p.x) / 2;
                  const my = (KANPUR.y + p.y) / 2;
                  const dx = p.x - KANPUR.x;
                  const dy = p.y - KANPUR.y;
                  const nx = -dy;
                  const ny = dx;
                  const len = Math.hypot(nx, ny) || 1;
                  const curve = 6;
                  const cx = mx + (nx / len) * curve;
                  const cy = my + (ny / len) * curve;
                  return (
                    <path
                      key={`def-${p.name}`}
                      id={`route-${i}`}
                      d={`M${KANPUR.x},${KANPUR.y} Q${cx},${cy} ${p.x},${p.y}`}
                      fill="none"
                    />
                  );
                })}
              </defs>

              {/* Soft drop shadow under landmass */}
              <ellipse cx="52" cy="118" rx="32" ry="3" fill="oklch(0 0 0 / 0.5)" />

              {/* India landmass */}
              <path
                d={INDIA_PATH}
                fill="url(#indiaFill)"
                stroke="url(#indiaStroke)"
                strokeWidth="0.45"
                filter="url(#glow)"
              />
              {/* Subtle inner highlight */}
              <path
                d={INDIA_PATH}
                fill="none"
                stroke="oklch(0.98 0.12 88 / 0.18)"
                strokeWidth="0.15"
                transform="translate(-0.3 -0.3)"
              />

              {/* Light sweep across the landmass */}
              <g clipPath="url(#mapClip)">
                <rect x="-40" y="0" width="40" height="120" fill="url(#indiaStroke)" opacity="0.12">
                  <animate attributeName="x" from="-40" to="140" dur="6s" repeatCount="indefinite" />
                </rect>
              </g>
              <clipPath id="mapClip">
                <path d={INDIA_PATH} />
              </clipPath>

              {/* Routes from Kanpur */}
              <g fill="none" filter="url(#glow)">
                {pins.map((_, i) => (
                  <use
                    key={`u-${i}`}
                    href={`#route-${i}`}
                    stroke="oklch(0.82 0.14 85)"
                    strokeWidth={active === i ? "0.45" : "0.28"}
                    strokeOpacity={active === i ? 0.95 : 0.55}
                    strokeDasharray="1.2 0.9"
                  >
                    <animate attributeName="stroke-dashoffset" from="0" to="-16" dur="3.5s" repeatCount="indefinite" />
                  </use>
                ))}
              </g>

              {/* Flowing light particles along routes */}
              {pins.map((_, i) => (
                <circle key={`p-${i}`} r="0.7" fill="oklch(0.98 0.12 88)" filter="url(#strongGlow)">
                  <animateMotion dur={`${3 + (i % 3) * 0.6}s`} repeatCount="indefinite" rotate="auto">
                    <mpath href={`#route-${i}`} />
                  </animateMotion>
                </circle>
              ))}

              {/* Destination markers */}
              {pins.map((p, i) => (
                <g
                  key={p.name}
                  onMouseEnter={() => setActive(i)}
                  onFocus={() => setActive(i)}
                  tabIndex={0}
                  className="cursor-pointer focus:outline-none"
                >
                  <circle cx={p.x} cy={p.y} r={active === i ? 4 : 2.6} fill="url(#goldOrb)" opacity={active === i ? 0.7 : 0.35} />
                  <circle cx={p.x} cy={p.y} r={active === i ? 1.4 : 1} fill="oklch(0.95 0.12 88)" filter="url(#glow)">
                    <animate
                      attributeName="r"
                      values={`${active === i ? 1.3 : 0.9};${active === i ? 1.9 : 1.4};${active === i ? 1.3 : 0.9}`}
                      dur="2.4s"
                      repeatCount="indefinite"
                    />
                  </circle>
                  <text
                    x={p.x + 2.4}
                    y={p.y + 0.9}
                    fontSize="2.2"
                    fill="var(--premium-white)"
                    opacity={active === i ? 1 : 0.75}
                    style={{ fontFamily: "ui-sans-serif, system-ui", letterSpacing: "0.04em" }}
                  >
                    {p.name}
                  </text>
                </g>
              ))}

              {/* KANPUR — HEAD OFFICE */}
              <g
                onClick={() => setKanpurOpen((o) => !o)}
                tabIndex={0}
                onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && setKanpurOpen((o) => !o)}
                role="button"
                aria-label="View Kanpur office locations"
                className="cursor-pointer focus:outline-none"
              >
                {/* expanding halo rings */}
                {[0, 1].map((k) => (
                  <circle key={k} cx={KANPUR.x} cy={KANPUR.y} r="3" fill="none" stroke="oklch(0.92 0.14 88)" strokeWidth="0.25" opacity="0.6">
                    <animate attributeName="r" from="2" to="9" dur="2.6s" begin={`${k * 1.3}s`} repeatCount="indefinite" />
                    <animate attributeName="opacity" from="0.7" to="0" dur="2.6s" begin={`${k * 1.3}s`} repeatCount="indefinite" />
                  </circle>
                ))}
                <circle cx={KANPUR.x} cy={KANPUR.y} r="6" fill="url(#goldOrb)" opacity="0.55" />
                <circle cx={KANPUR.x} cy={KANPUR.y} r="2.2" fill="oklch(0.98 0.14 88)" filter="url(#strongGlow)">
                  <animate attributeName="r" values="1.9;2.6;1.9" dur="1.8s" repeatCount="indefinite" />
                </circle>
                {/* badge */}
                <g transform={`translate(${KANPUR.x + 3.5} ${KANPUR.y - 5.5})`}>
                  <rect x="0" y="0" rx="1" ry="1" width="22" height="3.6" fill="oklch(0.13 0.02 260 / 0.9)" stroke="oklch(0.82 0.14 85)" strokeWidth="0.2" />
                  <text x="1" y="2.6" fontSize="1.8" fill="oklch(0.95 0.12 88)" letterSpacing="0.12em" style={{ fontFamily: "ui-sans-serif, system-ui" }}>
                    HEAD OFFICE
                  </text>
                </g>
                <text
                  x={KANPUR.x + 3.5}
                  y={KANPUR.y + 2}
                  fontSize="3"
                  fill="oklch(0.98 0.12 88)"
                  fontWeight="700"
                  style={{ fontFamily: "ui-serif, Georgia", letterSpacing: "0.05em" }}
                >
                  KANPUR
                </text>
              </g>
            </svg>

            {/* Kanpur offices popup */}
            <AnimatePresence>
              {kanpurOpen && (
                <>
                  <motion.button
                    type="button"
                    aria-label="Close offices"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={() => setKanpurOpen(false)}
                    className="absolute inset-0 z-10 bg-black/40 backdrop-blur-[2px] md:bg-transparent md:backdrop-blur-0 cursor-default"
                  />
                  <motion.div
                    initial={{ opacity: 0, y: 12, scale: 0.96 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 12, scale: 0.96 }}
                    transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                    className="absolute z-20 left-1/2 -translate-x-1/2 bottom-5 md:bottom-auto md:top-[42%] md:left-[44%] md:translate-x-0 w-[min(360px,calc(100%-2.5rem))] glass-strong rounded-2xl border border-[var(--gold)]/30 shadow-2xl p-5"
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <div className="text-[10px] uppercase tracking-[0.3em] text-gold mb-1">Head Office · Kanpur</div>
                        <div className="font-display text-lg text-premium-white">Two locations</div>
                      </div>
                      <button
                        onClick={() => setKanpurOpen(false)}
                        aria-label="Close"
                        className="grid place-items-center w-8 h-8 rounded-full glass text-luxury-gray hover:text-gold transition-colors"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                    <div className="space-y-3">
                      {KANPUR_OFFICES.map((o) => (
                        <div key={o.name} className="glass rounded-xl p-4 border border-white/5">
                          <div className="text-sm text-premium-white font-medium mb-1">{o.name}</div>
                          <div className="text-[12px] text-luxury-gray mb-3">{o.address}</div>
                          <a
                            href={o.mapUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-2 btn-gold px-4 py-2 rounded-full text-[11px] uppercase tracking-[0.2em] font-medium"
                          >
                            <Navigation className="w-3.5 h-3.5" /> Get Directions
                          </a>
                        </div>
                      ))}
                    </div>
                  </motion.div>
                </>
              )}
            </AnimatePresence>


            {/* Legend chip */}
            <div className="absolute bottom-5 left-5 right-5 flex items-center justify-between text-[10px] uppercase tracking-[0.3em]">
              <span className="px-3 py-1.5 glass rounded-full text-gold">13 States · 1 Hub</span>
              <span className="px-3 py-1.5 glass rounded-full text-luxury-gray">Live Network</span>
            </div>
          </div>

          {/* Active panel */}
          <motion.div
            key={a.name}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="glass-strong rounded-3xl overflow-hidden h-full flex flex-col"
          >
            <div className="relative aspect-square overflow-hidden">
              <AnimatePresence mode="wait">
                <motion.img
                  key={displayName}
                  src={selectedDest?.img ?? a.img}
                  alt={displayName}
                  initial={{ opacity: 0, scale: 1.04 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0 }}
                  transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                  className="absolute inset-0 w-full h-full object-cover"
                  loading="lazy"
                />
              </AnimatePresence>
              <div className="absolute inset-0 bg-gradient-to-t from-background via-background/30 to-transparent" />
              <div className="absolute top-5 left-5 px-3 py-1 glass rounded-full text-[10px] uppercase tracking-[0.3em] text-gold">
                {displayTours} Tours · From Kanpur
              </div>
              {selectedDest && (
                <div className="absolute top-5 right-5 px-3 py-1 glass rounded-full text-[10px] uppercase tracking-[0.3em] text-luxury-gray">
                  {a.name}
                </div>
              )}
            </div>
            <div className="p-7">
              <div className="text-[11px] uppercase tracking-[0.3em] text-gold mb-2">
                {selectedDest ? "Featured Destination" : "Featured State"}
              </div>
              <AnimatePresence mode="wait">
                <motion.div
                  key={displayName + "-text"}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -4 }}
                  transition={{ duration: 0.35 }}
                >
                  <h3 className="font-display text-4xl mb-3">{displayName}</h3>
                  <p className="text-luxury-gray text-sm leading-relaxed mb-6">{displayDesc}</p>
                </motion.div>
              </AnimatePresence>
              <div className="flex items-center justify-between border-t border-white/10 pt-5">
                <div>
                  <div className="text-[10px] uppercase tracking-[0.2em] text-luxury-gray">Starting from</div>
                  <div className="font-display text-2xl text-gold">{displayPrice}</div>
                </div>
                {selectedDest?.packageSlug ? (
                  <Link to="/tours" hash={selectedDest.packageSlug} className="btn-gold px-5 py-3 rounded-full text-xs uppercase tracking-[0.2em] font-medium">
                    View Tour
                  </Link>
                ) : (
                  <Link to="/tours" className="btn-gold px-5 py-3 rounded-full text-xs uppercase tracking-[0.2em] font-medium">
                    View Tours
                  </Link>
                )}
              </div>

              {/* State selector pills */}
              <div className="mt-6 flex flex-wrap gap-2">
                {pins.map((p, i) => (
                  <button
                    key={p.name}
                    onClick={() => setActive(i)}
                    className={`px-3 py-1.5 rounded-full text-[11px] tracking-wide transition-colors ${active === i ? "bg-[var(--gold)] text-[var(--primary-foreground)]" : "glass text-luxury-gray hover:text-premium-white"}`}
                  >
                    {p.name}
                  </button>
                ))}
              </div>

              {/* Destination pills */}
              <div className="mt-4 pt-4 border-t border-white/5">
                <div className="text-[10px] uppercase tracking-[0.3em] text-luxury-gray mb-3">
                  Destinations in {a.name}
                </div>
                <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto overflow-x-hidden pr-1">
                  {a.destinations.map((d, i) => (
                    <button
                      key={d.name}
                      onClick={() => setDestIndex(destIndex === i ? null : i)}
                      className={`px-3 py-1.5 rounded-full text-[11px] tracking-wide transition-colors ${destIndex === i ? "bg-[var(--gold)] text-[var(--primary-foreground)]" : "glass text-luxury-gray hover:text-premium-white"}`}
                    >
                      {d.name}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
